                            Duration = duration or 4,
                        })
                    end)
                end
            end

            local function canonicalQuality(value)
                local s = string.lower(tostring(value or ""))

                for _, quality in ipairs(qualities) do
                    if string.find(s, string.lower(quality), 1, true) then
                        return quality
                    end
                end

                return nil
            end

            local function normalizePercent(value)
                local n = tonumber(value)
                if not n then
                    return nil
                end

                if n >= -20.05 and n <= 18.05 then
                    return n
                end

                return nil
            end

            local function parsePercent(value)
                local s = tostring(value or "")
                local numberText = string.match(
                    s,
                    "([%+%-]?%d+%.?%d*)%s*%%"
                )

                if numberText then
                    return normalizePercent(tonumber(numberText))
                end

                return nil
            end

            local function inferQuality(percent)
                local p = normalizePercent(percent)
                if p == nil then
                    return nil
                end

                if p >= 15 then
                    return "Transcendent"
                elseif p >= 10 then
                    return "Artifact"
                elseif p >= 5 then
                    return "Divine"
                elseif p >= 0 then
                    return "Pristine"
                elseif p >= -10 then
                    return "Refined"
                elseif p >= -20 then
                    return "Broken"
                end

                return nil
            end

            local function getInventory()
                return ctx.LocalPlayer
                    and ctx.LocalPlayer:FindFirstChild("Inventory")
                    or nil
            end

            local function readItemState(item, allowUI)
                if not item or not item.Parent then
                    return nil, nil
                end

                local quality = nil
                local percent = nil
                local attrs = item:GetAttributes()

                local qualityKeys = {
                    "ReforgeQuality",
                    "QualityName",
                    "Quality",
                    "ReforgeGrade",
                    "QualityGrade",
                }

                local percentKeys = {
                    "ReforgePercent",
                    "ReforgePercentage",
                    "QualityPercent",
                    "QualityPercentage",
                    "ReforgeBonusPercent",
                    "QualityBonusPercent",
                }

                for _, key in ipairs(qualityKeys) do
                    local value = attrs[key]
                    if value ~= nil then
                        quality = canonicalQuality(value)
                        if quality then
                            break
                        end
                    end
                end

                for _, key in ipairs(percentKeys) do
                    local value = attrs[key]
                    if value ~= nil then
                        percent = normalizePercent(value)
                            or parsePercent(value)

                        if percent ~= nil then
                            break
                        end
                    end
                end

                if not quality or percent == nil then
                    for key, value in pairs(attrs) do
                        local keyLower = string.lower(tostring(key))
                        local relevant =
                            string.find(keyLower, "reforge", 1, true)
                            or string.find(keyLower, "quality", 1, true)

                        if relevant then
                            if not quality then
                                quality = canonicalQuality(value)
                            end

                            if percent == nil then
                                percent = normalizePercent(value)
                                    or parsePercent(value)
                            end
                        end
                    end
                end

                if not quality or percent == nil then
                    local inspected = 0

                    for _, child in ipairs(item:GetDescendants()) do
                        if child:IsA("ValueBase") then
                            inspected = inspected + 1
                            if inspected > 80 then
                                break
                            end

                            local keyLower = string.lower(child.Name)
                            local relevant =
                                string.find(keyLower, "reforge", 1, true)
                                or string.find(keyLower, "quality", 1, true)

                            if relevant then
                                local value = child.Value

                                if not quality then
                                    quality = canonicalQuality(value)
                                end

                                if percent == nil then
                                    percent = normalizePercent(value)
                                        or parsePercent(value)
                                end
                            end
                        end
                    end
                end

                if not quality and percent ~= nil then
                    quality = inferQuality(percent)
                end

                if allowUI ~= false then
                    local uiQuality, uiPercent = M.ReadUIState()

                    if uiQuality and uiPercent ~= nil then
                        quality = uiQuality
                        percent = uiPercent
                    end
                end

                return quality, percent
            end

            local function resolveResultLabel(force)
                local playerGui = ctx.LocalPlayer
                    and ctx.LocalPlayer:FindFirstChildOfClass("PlayerGui")
                local main = playerGui and playerGui:FindFirstChild("Main")
                local root = main and main:FindFirstChild("Reforge", true)

                if not root then
                    cachedResultLabel = nil
                    cachedReforgeRoot = nil
                    return nil
                end

                if not force
                    and cachedResultLabel
                    and cachedResultLabel.Parent
                    and cachedReforgeRoot == root then
                    return cachedResultLabel
                end

                -- Avoid repeated full scans if no valid label exists yet.
                if not force
                    and cachedReforgeRoot == root
                    and os.clock() - lastLabelScan < 0.50 then
                    return nil
                end

                lastLabelScan = os.clock()
                cachedReforgeRoot = root
                cachedResultLabel = nil

                local bestLabel = nil
                local bestScore = -math.huge
                local scanned = 0

                for _, gui in ipairs(root:GetDescendants()) do
                    if gui:IsA("TextLabel") or gui:IsA("TextButton") then
                        scanned = scanned + 1
                        if scanned > 500 then
                            break
                        end

                        local visible = true
                        pcall(function()
                            visible = gui.Visible
                        end)

                        if visible then
                            local txt = tostring(gui.Text or "")
                            local quality = canonicalQuality(txt)
                            local percent = parsePercent(txt)

                            if quality and percent ~= nil then
                                local percentCount = 0
                                for _ in string.gmatch(txt, "%%") do
                                    percentCount = percentCount + 1
                                end

                                if percentCount == 1 then
                                    local score = 0

                                    if #txt <= 40 then
                                        score = score + 10
                                    end

                                    pcall(function()
                                        score = score
                                            + math.min(
                                                tonumber(gui.TextSize) or 0,
                                                40
                                            ) * 0.25
                                    end)

                                    pcall(function()
                                        local absY = gui.AbsolutePosition.Y
                                        local rootY = root.AbsolutePosition.Y

                                        if absY <= rootY
                                            + math.max(
                                                root.AbsoluteSize.Y * 0.45,
                                                160
                                            ) then
                                            score = score + 4
                                        end
                                    end)

                                    if score > bestScore then
                                        bestScore = score
                                        bestLabel = gui
                                    end
                                end
                            end
                        end
                    end
                end

                cachedResultLabel = bestLabel
                return bestLabel
            end

            function M.ReadUIState()
                local label = resolveResultLabel(false)

                if label and label.Parent then
